(11, 'Lose50%RewardsAtPort', '<kalguurred>{Trade disruptions at port caused economic shocks. We only received half of what we expected.}', '[]', 0, 50, 0, 0, 1, '<kalguurlightgrey>{Our expected returns have been halved!}', 1),
