(17, 'LoseCrewMemberOverboardReturning', '<kalguurred>{One of our crew decided to stay at port and start a new life.}', '[]', 0, 0, 0, 1, 1, '<kalguurlightgrey>{One of our crewmembers has been lost!}', 5),
